      var teamChip = "";
      if (lt) teamChip = ' <span class="team-chip ' + lt.team + '">' + (lt.team === "blue" ? "🔵 Mavi" : "🔴 Kırmızı") + " · " + esc(lt.week) + "</span>";
      var hl = firstSentence(NOTES[c.name] || "");
